const read = (name) => { try { return String($env[name] ?? '').trim(); } catch { return ''; } };
const rawOrigin = read('PAI_LOOP_API_BASE_URL') || 'https://pai-loop-demo.onrender.com';
if (!/^https?:\/\/[A-Za-z0-9.-]+(?::\d+)?(?:\/[^\s]*)?$/i.test(rawOrigin) || rawOrigin.includes('@') || rawOrigin.includes('\\')) throw new Error('PAI_LOOP_API_BASE_URL is unsafe');
const emergencyDisabled = String(read('PAI_LOOP_EMERGENCY_DISABLE')).toLowerCase() === 'true';
return [{ json: { runtime: { apiBaseUrl: rawOrigin.replace(/\/+$/, ''), enabled: !emergencyDisabled, emergencyDisabled, triggerSource: 'manual', queueName: 'BACKFILL', resumeOnly: false, dryRun: false, chunkSize: 3, maxTotal: 3000, executionLimit: 30, includeRetryable: false, retryCooldownHours: 24, reservationTtlHours: 6, maxContinuations: 128 } } }];

const response = $json?.body && typeof $json.body === 'object' ? $json.body : $json;
let runtime = null; try { runtime = $node['Build Scheduled Continuation Runtime'].json.runtime; } catch {} if (!runtime) { runtime = $node['Build Fail-Closed Backfill Runtime'].json.runtime; }
if (!response || !['RUNNING','COMPLETED','PARTIAL','DEAD_LETTER','NO_ACTIVE'].includes(response.status)) throw new Error('continuation plan status invalid');
if (response.status === 'NO_ACTIVE') { if (response.job_id !== null || response.segment_id !== null || response.planned !== 0 || response.offered !== 0 || response.chunks?.length !== 0 || response.chunk_indices?.length !== 0) throw new Error('NO_ACTIVE must be a zero-work response'); return [{ json: { runtime, operation: { jobId: null, segmentId: null, status: 'NO_ACTIVE', queueName: response.queue_name, planned: 0, attempted: 0, remaining: 0, inFlight: 0, offered: 0, chunks: [], chunkIndices: [], continuationRequired: false, continuationRound: 0 } } }]; }
if (!/^[0-9a-f-]{36}$/i.test(String(response.job_id ?? '')) || !['BACKFILL','DAILY'].includes(response.queue_name) || response.policy !== 'OPEN_NOT_SELECTED_THEN_COOLED_RETRY') throw new Error('continuation operation identity invalid');
for (const field of ['planned','attempted','remaining','in_flight','offered','continuation_round','max_continuations']) if (!Number.isSafeInteger(response[field]) || response[field] < 0) throw new Error(`continuation ${field} invalid`);
if (response.planned !== response.attempted + response.remaining || response.offered > runtime.executionLimit || response.max_continuations > 128) throw new Error('continuation hard budget invalid');
if (!Array.isArray(response.notice_keys) || response.notice_keys.length !== response.offered || !Array.isArray(response.chunks) || response.chunks.flat().length !== response.offered || response.chunks.some((chunk) => chunk.length < 1 || chunk.length > 3) || !Array.isArray(response.chunk_indices) || response.chunk_indices.length !== response.chunks.length) throw new Error('continuation chunks invalid');
const keys = response.notice_keys.map((value) => String(value));
if (new Set(keys).size !== keys.length || keys.some((key) => !key || key.length > 160) || JSON.stringify(response.chunks.flat().map(String)) !== JSON.stringify(keys)) throw new Error('continuation keys invalid');
if (new Set(response.chunk_indices).size !== response.chunk_indices.length || response.chunk_indices.some((value) => !Number.isSafeInteger(value) || value < 0)) throw new Error('continuation chunk indices invalid');
if (response.offered > 0 && !/^[0-9a-f-]{36}$/i.test(String(response.segment_id ?? ''))) throw new Error('offered continuation requires a segment lease');
if (response.offered === 0 && (response.chunks.length !== 0 || response.chunk_indices.length !== 0)) throw new Error('zero-offer continuation must not fan out');
return [{ json: { runtime, operation: { jobId: response.job_id, segmentId: response.segment_id, status: response.status, queueName: response.queue_name, planned: response.planned, attempted: response.attempted, remaining: response.remaining, inFlight: response.in_flight, offered: response.offered, chunks: response.chunks, chunkIndices: response.chunk_indices, continuationRequired: response.continuation_required, continuationRound: response.continuation_round, maxContinuations: response.max_continuations, warnings: response.warnings ?? [] } } }];

const input = $json;
if (!input.operation.segmentId || !Array.isArray(input.operation.chunkIndices) || input.operation.chunkIndices.length !== input.operation.chunks.length) throw new Error('durably leased continuation chunks required');
return input.operation.chunks.map((noticeKeys, localIndex) => ({ json: { runtime: input.runtime, operation: { jobId: input.operation.jobId, segmentId: input.operation.segmentId }, analysisChunk: { segmentId: input.operation.segmentId, chunkIndex: input.operation.chunkIndices[localIndex], noticeKeys } } }));

const response = $json?.body && typeof $json.body === 'object' ? $json.body : $json;
if (!response || !['COMPLETED','PARTIAL'].includes(response.status) || !/^[0-9a-f-]{36}$/i.test(String(response.job_id ?? ''))) throw new Error('analysis chunk identity/status invalid');
for (const field of ['requested','processed','completed','skipped','failed','openai_calls']) if (!Number.isSafeInteger(response[field]) || response[field] < 0) throw new Error(`analysis chunk ${field} invalid`);
if (response.requested < 1 || response.requested > 3 || response.processed !== response.completed + response.skipped + response.failed || response.processed > response.requested || response.openai_calls > response.requested) throw new Error('analysis chunk bounds/counts invalid');
if (!Array.isArray(response.results) || response.results.length !== response.processed || !Array.isArray(response.warnings)) throw new Error('analysis chunk results invalid');
const keys = response.results.map((item) => String(item.notice_key ?? ''));
if (new Set(keys).size !== keys.length || keys.some((key) => !key || key.length > 160)) throw new Error('analysis chunk result keys invalid');
return { json: { childJobId: response.job_id, status: response.status, requested: response.requested, processed: response.processed, completed: response.completed, skipped: response.skipped, failed: response.failed, openaiCalls: response.openai_calls, noticeKeys: keys, warnings: response.warnings.slice(0, 20) } };

const rows = $input.all().map((item) => item.json);
const operation = $node['Validate Backfill Plan'].json.operation;
const totals = { requested: 0, processed: 0, completed: 0, skipped: 0, failed: 0, openaiCalls: 0 };
const keys = [];
for (const row of rows) { for (const field of Object.keys(totals)) totals[field] += Number(row[field] ?? 0); keys.push(...row.noticeKeys); }
if (rows.length !== operation.chunks.length || new Set(keys).size !== keys.length || totals.requested !== operation.offered || totals.processed !== totals.completed + totals.skipped + totals.failed) throw new Error('continuation aggregate is duplicated or incomplete');
return [{ json: { runtime: $node['Validate Backfill Plan'].json.runtime, operation: { ...operation, chunksExecuted: rows.length, ...totals, childJobs: rows.map((row) => row.childJobId), warnings: [...new Set(rows.flatMap((row) => row.warnings ?? []))].slice(0, 50) } } }];

const response = $json?.body && typeof $json.body === 'object' ? $json.body : $json;
if (!response || !['COMPLETED','PARTIAL','DEAD_LETTER'].includes(response.status)) throw new Error('continuation final status invalid');
if (response.segment_id !== null || response.offered !== 0 || response.in_flight !== 0 || response.chunks?.length !== 0 || response.chunk_indices?.length !== 0) throw new Error('continuation segment lease was not cleared');
if (!Number.isSafeInteger(response.planned) || !Number.isSafeInteger(response.attempted) || !Number.isSafeInteger(response.remaining) || !Number.isSafeInteger(response.openai_calls) || response.openai_calls < 0 || response.attempted + response.remaining !== response.planned) throw new Error('continuation final counts invalid');
return [{ json: { jobId: response.job_id, queueName: response.queue_name, status: response.status, planned: response.planned, attempted: response.attempted, completed: response.completed, partial: response.partial, failed: response.failed, remaining: response.remaining, inFlight: response.in_flight, openaiCalls: response.openai_calls, continuationRequired: response.remaining > 0 && response.status !== 'DEAD_LETTER', continuationRound: response.continuation_round, childJobs: response.child_jobs, warnings: response.warnings, notificationEvent: response.status === 'COMPLETED' ? 'ANALYSIS_OPERATION_COMPLETED' : (response.status === 'DEAD_LETTER' ? 'ANALYSIS_OPERATION_DEAD_LETTER' : 'ANALYSIS_OPERATION_PROGRESS') } }];

